import { test, expect } from '@playwright/test';

test.describe('Date Picker Keyboard Accessibility', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('about:blank');
    await page.setContent(`
      <div>
        <label for="datepicker">Select a date:</label>
        <input 
          id="datepicker" 
          type="date" 
          aria-label="Date picker"
          aria-describedby="date-help"
        />
        <div id="date-help">Use arrow keys to navigate dates</div>
        <button id="today-btn">Today</button>
        <button id="clear-btn">Clear</button>
      </div>
    `);
  });

  test('should open date picker with keyboard and navigate using arrow keys', async ({ page }) => {
    const datepicker = page.getByLabel('Date picker');

    // Focus the date picker
    await datepicker.focus();

    // Verify it's focused
    await expect(datepicker).toBeFocused();

    // Type a date using keyboard
    await datepicker.type('12252024');

    // Verify the date was entered
    const value = await datepicker.inputValue();
    expect(value).toBe('2024-12-25');
  });

  test('should navigate date picker with arrow keys and modify date', async ({ page }) => {
    const datepicker = page.getByLabel('Date picker');

    // Focus and enter initial date
    await datepicker.focus();
    await datepicker.type('01152024');

    // Use arrow keys to increment the date
    await datepicker.press('ArrowUp');

    // Verify focus remains on the input
    await expect(datepicker).toBeFocused();

    // Clear and enter new date
    await datepicker.clear();
    await datepicker.type('06302024');

    const value = await datepicker.inputValue();
    expect(value).toBe('2024-06-30');
  });

  test('should support Tab navigation between date picker and buttons', async ({ page }) => {
    const datepicker = page.getByLabel('Date picker');
    const todayBtn = page.getByRole('button', { name: 'Today' });
    const clearBtn = page.getByRole('button', { name: 'Clear' });

    // Start at date picker
    await datepicker.focus();
    await expect(datepicker).toBeFocused();

    // Tab to Today button
    await page.keyboard.press('Tab');
    await expect(todayBtn).toBeFocused();

    // Tab to Clear button
    await page.keyboard.press('Tab');
    await expect(clearBtn).toBeFocused();

    // Shift+Tab back to Today button
    await page.keyboard.press('Shift+Tab');
    await expect(todayBtn).toBeFocused();

    // Shift+Tab back to date picker
    await page.keyboard.press('Shift+Tab');
    await expect(datepicker).toBeFocused();
  });

  test('should allow clearing date with keyboard', async ({ page }) => {
    const datepicker = page.getByLabel('Date picker');
    const clearBtn = page.getByRole('button', { name: 'Clear' });

    // Enter a date
    await datepicker.focus();
    await datepicker.type('03152024');

    let value = await datepicker.inputValue();
    expect(value).toBe('2024-03-15');

    // Navigate to clear button and activate it
    await page.keyboard.press('Tab');
    await page.keyboard.press('Tab');
    await page.keyboard.press('Enter');

    // Verify date is cleared
    value = await datepicker.inputValue();
    expect(value).toBe('');
  });

  test('should support Enter key to confirm date selection', async ({ page }) => {
    const datepicker = page.getByLabel('Date picker');

    // Focus date picker
    await datepicker.focus();

    // Type date
    await datepicker.type('07042024');

    // Press Enter to confirm
    await datepicker.press('Enter');

    // Verify the date is still set
    const value = await datepicker.inputValue();
    expect(value).toBe('2024-07-04');
  });

  test('should support Escape key to cancel date picker', async ({ page }) => {
    const datepicker = page.getByLabel('Date picker');

    // Focus and enter a date
    await datepicker.focus();
    await datepicker.type('11112024');

    // Press Escape
    await datepicker.press('Escape');

    // Verify focus is still on the input
    await expect(datepicker).toBeFocused();
  });

  test('should have proper ARIA attributes for accessibility', async ({ page }) => {
    const datepicker = page.getByLabel('Date picker');

    // Verify aria-label is present
    const ariaLabel = await datepicker.getAttribute('aria-label');
    expect(ariaLabel).toBe('Date picker');

    // Verify aria-describedby is present
    const ariaDescribedBy = await datepicker.getAttribute('aria-describedby');
    expect(ariaDescribedBy).toBe('date-help');

    // Verify the description text exists
    const helpText = page.locator('#date-help');
    await expect(helpText).toContainText('Use arrow keys to navigate dates');
  });

  test('should allow keyboard-only users to select specific date ranges', async ({ page }) => {
    const datepicker = page.getByLabel('Date picker');

    // Focus the date picker
    await datepicker.focus();

    // Enter start date
    await datepicker.type('01012024');
    let value = await datepicker.inputValue();
    expect(value).toBe('2024-01-01');

    // Clear and enter end date
    await datepicker.clear();
    await datepicker.type('12312024');
    value = await datepicker.inputValue();
    expect(value).toBe('2024-12-31');
  });
});
